package dev.veltraph.client.chocolate;
import java.math.BigDecimal;
import java.util.*;
/** Only captured XV activation and III-to-IV prestige contracts authorize these actions. */
final class ChocolateConsequentialParser {
    static final String PREVIEW="Confirm Prestige";
    static final List<String> TERMS=List.of("▶ Resets Chocolate Factory progress.","▶ Resets Chocolate.","▶ Chocolate Production Multiplier: 1.25 ➜ 1.5x","▶ Max Rabbit Rarity: EPIC ➜ LEGENDARY","▶ Max Chocolate: 5B ➜ 25B","▶ Max Employee: [160] ➜ [180] Director","▶ Rabbit Hitman Slots: 18 ➜ 22","▶ Rabbit Hitman progress is kept.","▶ Hoppity's Collection progress is kept.","▶ Rabbit Barn progress is kept.","▶ +25 SkyBlock XP");
    static boolean eligiblePrestige(ChocolateFactoryObservation o){if(o==null)return false;var s=CapturedChocolateFactoryParser.parse(o.title(),o.rows());var row=o.rows().get(27);return s.complete()&&s.factoryLevel()==3&&row!=null&&row.itemId().equals("minecraft:dropper")&&row.lore().contains("PRESTIGE ➜ Chocolate Factory IV")&&row.lore().contains("Click to prestige!")&&row.lore().stream().filter(l->l.startsWith("▶ ")).toList().equals(TERMS);}
    static boolean preview(ChocolateFactoryObservation o){if(o==null||!o.title().equals(PREVIEW))return false;var row=o.rows().get(11);var cancel=o.rows().get(15);return java.util.stream.IntStream.range(0,27).allMatch(i->o.rows().containsKey(i)&&!o.rows().get(i).playerInventory())&&row!=null&&row.count()==1&&row.itemId().equals("minecraft:dropper")&&row.name().equals("PRESTIGE ➜ Chocolate Factory IV")&&row.lore().contains("Click to prestige!")&&row.lore().stream().filter(l->l.startsWith("▶ ")).toList().equals(TERMS)&&cancel!=null&&cancel.itemId().equals("minecraft:red_terracotta")&&cancel.name().equals("Cancel");}
    static Optional<CapturedChocolateFactoryParser.Tower> tower(ChocolateFactoryObservation o){if(o==null)return Optional.empty();return CapturedChocolateFactoryParser.tower(o.rows()).filter(t->t.level()==15&&t.displayedBoost().filter(v->v.compareTo(new BigDecimal("1.5"))==0).isPresent()&&t.maxCharges().orElse(-1)==3);}
    static boolean towerReady(ChocolateFactoryObservation o){return tower(o).filter(t->t.status().equals("INACTIVE")&&t.charges().orElse(0)>0&&t.charges().orElse(4)<=3).isPresent()&&o.rows().get(38).lore().contains("Right-click to activate!");}
    static boolean reset(ChocolateFactoryObservation before,ChocolateFactoryObservation after){var a=CapturedChocolateFactoryParser.parse(before.title(),before.rows());var b=CapturedChocolateFactoryParser.parse(after.title(),after.rows());if(!b.complete()||b.factoryLevel()!=4||b.balance().orElse(BigDecimal.ONE).signum()!=0||b.prestigeProgress().orElse(BigDecimal.ONE).signum()!=0||!b.allTime().equals(a.allTime())||b.capacity().filter(v->v.compareTo(new BigDecimal("25000000000"))==0).isEmpty())return false;var row=after.rows().get(27);if(!row.lore().containsAll(List.of("Chocolate Production Multiplier: 1.5x","Max Rabbit Rarity: LEGENDARY","Max Employee: [180] Director","Max Rabbit Hitman Slots: 22")))return false;for(int slot:new int[]{35,50})if(!Objects.equals(before.rows().get(slot).fullIdentity(),after.rows().get(slot).fullIdentity()))return false;for(String line:before.rows().get(45).lore())if(line.contains("(Hoppity's Collection)")||line.contains("(Prestige Chocolate Realm)"))if(!after.rows().get(45).lore().contains(line))return false;var tower=CapturedChocolateFactoryParser.tower(after.rows());return tower.filter(t->t.level()==1&&t.status().equals("INACTIVE")&&t.charges().orElse(-1)==0).isPresent()&&b.targets().get("rabbit_bro")!=null&&b.targets().get("rabbit_bro").level()==0;}
}
